// Generated by allium:propagate from spec/recipe-ideas.allium (rule ResearchIdea: inspiration_text, the idea's
// inspiration link read only under the import's safe-fetch rules; null when absent or not fetchable). Do not edit by
// hand: change the spec and propagate.
import http from "node:http";
import type { AddressInfo } from "node:net";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { WebInspirationReader } from "../../../src/infrastructure/ideas/web-inspiration-reader.js";

const limits = { maxBytes: 5000, timeoutMs: 2000, maxRedirects: 3 };
const open = { allowed: () => true, allowedPort: () => true };
let server: http.Server;
let base: string;

beforeAll(async () => {
  server = http.createServer((req, res) => {
    const url = req.url ?? "";
    const send = (body: string, type = "text/html; charset=utf-8") => {
      res.writeHead(200, { "content-type": type });
      res.end(body);
    };
    if (url === "/inspo")
      return send("<html><body><h1>Ofenkürbis</h1><p>Mit Salbei und Feta.</p><script>evil()</script></body></html>");
    if (url === "/json") return send('{"a":1}', "application/json");
    if (url === "/big") return send(`<p>${"x".repeat(6000)}</p>`);
    if (url === "/to-private") {
      res.writeHead(302, { location: "http://10.0.0.1/secret" });
      return res.end();
    }
    if (url === "/loop") {
      res.writeHead(302, { location: "/loop" });
      return res.end();
    }
    if (url === "/slow") return void setTimeout(() => send("<p>late</p>"), 3000);
    res.writeHead(404);
    res.end();
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
afterAll(() => new Promise<void>((r) => server.close(() => r())));

describe("WebInspirationReader", () => {
  it("reads the text of an HTML page, without its markup or scripts", async () => {
    const text = await new WebInspirationReader({ ...open, ...limits }).readInspiration(`${base}/inspo`);
    expect(text).toContain("Ofenkürbis");
    expect(text).toContain("Mit Salbei und Feta.");
    expect(text).not.toContain("<");
    expect(text).not.toContain("evil()");
  });

  it("refuses a private address by default (the import's safe-fetch rules), giving null rather than failing", async () => {
    expect(await new WebInspirationReader({ allowedPort: () => true }).readInspiration(`${base}/inspo`)).toBeNull();
  });

  it.each([
    ["not HTML", "/json"],
    ["too large", "/big"],
    ["redirected to a private address", "/to-private"],
    ["redirected too often", "/loop"],
    ["missing", "/missing"],
    ["too slow", "/slow"],
  ])("gives null for a page that is %s", async (_why, path) => {
    expect(
      await new WebInspirationReader({ ...open, ...limits, timeoutMs: 500 }).readInspiration(`${base}${path}`),
    ).toBeNull();
  });

  it.each(["not a link", "ftp://example.org/x", "javascript:alert(1)", ""])(
    "gives null for %j instead of throwing",
    async (address) => {
      expect(await new WebInspirationReader({ ...open, ...limits }).readInspiration(address)).toBeNull();
    },
  );
});
